import json,socket,ipaddress,urllib.request,urllib.error
h="serveriptv.duckdns.org"
out={"target":h}
for name,label in [("duckdns.org","dns_control"),(h,"dns_target")]:
    try:
        addresses=sorted(set(x[4][0] for x in socket.getaddrinfo(name,None,proto=socket.IPPROTO_TCP)))
        out[label]={"resolved":bool(addresses),"addresses":len(addresses),"public_ipv4":sum(1 for a in addresses if ipaddress.ip_address(a).version==4 and ipaddress.ip_address(a).is_global)}
    except (socket.gaierror,OSError) as exc:
        out[label]={"resolved":False,"error_type":type(exc).__name__,"error_code":getattr(exc,"errno",None)}
try:
    with socket.create_connection(("127.0.0.1",8096),timeout=2): out["jellyfin_local_8096_tcp"]="open"
except OSError as exc: out["jellyfin_local_8096_tcp"]="closed_or_filtered:"+type(exc).__name__
try:
    req=urllib.request.Request("http://127.0.0.1:8096/System/Info/Public",headers={"User-Agent":"Ferrari-Jellyfin-Readonly-Audit"})
    with urllib.request.urlopen(req,timeout=3) as rsp:
        data=json.load(rsp)
        out["jellyfin_local_public_api"]={"http":rsp.status,"jellyfin_version_present":isinstance(data,dict) and "Version" in data}
except Exception as exc: out["jellyfin_local_public_api"]={"error_type":type(exc).__name__}
for scheme in ["https","http"]:
    try:
        req=urllib.request.Request(scheme+"://"+h+"/System/Info/Public",headers={"User-Agent":"Ferrari-Jellyfin-Readonly-Audit"})
        with urllib.request.urlopen(req,timeout=6) as rsp:
            body=rsp.read(3000)
            try: parsed=json.loads(body)
            except (ValueError,UnicodeDecodeError): parsed={}
            out[scheme]={"http":rsp.status,"jellyfin_public_info":isinstance(parsed,dict) and "Version" in parsed,"final_url_same_host":urllib.parse.urlparse(rsp.url).hostname==h}
    except urllib.error.HTTPError as exc: out[scheme]={"http":exc.code,"jellyfin_public_info":False}
    except Exception as exc: out[scheme]={"error_type":type(exc).__name__,"error_reason":str(getattr(exc,"reason",""))[:100]}
print(json.dumps(out,sort_keys=True))
